import 'package:meta/meta.dart';import '../../../../../../Core/Models/product_details_model.dart';import '../../data/models/product_preview_entities.dart';@immutableclass HomeStateModel {  final String errorMessage ;  final List<ProductPreviewEntities> productsFeatured;  final List<ProductPreviewEntities> productsPopular;  final ProductDetailsModel? productDetails;  final List<ProductPreviewEntities> favoriteProductDetails;  final Map<String, bool> isLoading;  const HomeStateModel({    this.productsFeatured = const [],    this.productsPopular = const [],    this.isLoading = const {},    this.errorMessage ="",    this.productDetails,    this.favoriteProductDetails = const [],  });  HomeStateModel copyWith({    List<ProductPreviewEntities>? productsFeatured,    String? errorMessage,    List<ProductPreviewEntities>? productsPopular,    Map<String, bool>? isLoading,    ProductDetailsModel? productDetails,    List<ProductPreviewEntities>? favoriteProductDetails,  }) {    return HomeStateModel(        productDetails: productDetails ?? this.productDetails,        productsFeatured: productsFeatured ?? this.productsFeatured,        productsPopular: productsPopular ?? this.productsPopular,        isLoading: isLoading ?? this.isLoading,        errorMessage: errorMessage ?? this.errorMessage,        favoriteProductDetails:        favoriteProductDetails ?? this.favoriteProductDetails,        );  }}